#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int to, next;
} Edge;

static int *head;
static Edge *edges;
static int edge_cnt = 0;

static char *label;
static int *vis;

void add_edge(int u, int v) {
    edges[edge_cnt].to = v;
    edges[edge_cnt].next = head[u];
    head[u] = edge_cnt++;
}

typedef struct {
    int hasA, hasB;
    int bip;
    int cnt[2];
} CompInfo;

void dfs_component(int start, CompInfo *info) {
    int *stack = (int *)malloc(sizeof(int) * 200005);
    int top = 0;
    stack[top++] = start;
    vis[start] = 1;

    while (top) {
        int u = stack[--top];
        int c = vis[u] - 1;  // 0 or 1
        info->cnt[c]++;
        if (label[u] == 'A') info->hasA = 1;
        else info->hasB = 1;

        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            if (!vis[v]) {
                vis[v] = 3 - vis[u]; // 1<->2
                stack[top++] = v;
            } else if (vis[v] == vis[u]) {
                info->bip = 0;
            }
        }
    }
    free(stack);
}

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    label = (char *)malloc((N + 1) * sizeof(char));
    head = (int *)malloc((N + 1) * sizeof(int));
    vis = (int *)calloc(N + 1, sizeof(int));
    edges = (Edge *)malloc(sizeof(Edge) * (2 * M + 5));

    for (int i = 1; i <= N; i++) head[i] = -1;

    char s[200005];
    scanf("%s", s);
    for (int i = 1; i <= N; i++) label[i] = s[i - 1];

    for (int i = 0; i < M; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        add_edge(u, v);
        add_edge(v, u);
    }

    int hasAB_edge = 0;
    for (int u = 1; u <= N; u++) {
        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            if (u < v && label[u] != label[v]) {
                hasAB_edge = 1;
            }
        }
    }

    if (!hasAB_edge) {
        printf("No\n");
        return 0;
    }

    for (int i = 1; i <= N; i++) {
        if (!vis[i]) {
            CompInfo info;
            info.hasA = info.hasB = 0;
            info.bip = 1;
            info.cnt[0] = info.cnt[1] = 0;

            dfs_component(i, &info);

            if (info.hasA && info.hasB) {
                if (!info.bip || info.cnt[0] != info.cnt[1]) {
                    printf("Yes\n");
                    return 0;
                }
            }
        }
    }

    printf("No\n");
    return 0;
}

