#include <bits/stdc++.h>
using namespace std;

/*
Interpretation:
Nusook chooses any start vertex and walks along edges, recording labels of visited vertices.
We must decide whether she can generate every finite string over {'A','B'}.

Key observation:
This is possible iff in some connected component:
1) there is at least one 'A' vertex and at least one 'B' vertex, and
2) the component is not bipartite by labels in the sense that there exists
   an edge connecting equal labels somewhere in that component.

Why:
- If a connected component contains both labels, then from any label we can reach the other.
- If every edge in the component connects different labels only, then every walk alternates A/B,
  so strings like "AA" or "BB" are impossible.
- If there is an equal-label edge, say X-X, then we can stay on label X for one extra step.
  Since the component also contains the other label and is connected, we can move between labels,
  and by inserting back-and-forth traversals on equal-label edges we can realize arbitrary run lengths.
  Hence any binary string can be constructed.

So we just inspect each connected component:
- hasA?
- hasB?
- hasSameEdge? (an edge whose endpoints have same label)

If any component satisfies all three, answer Yes; otherwise No.
*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;
    string s;
    cin >> s;

    vector<vector<int>> g(N);
    vector<pair<int,int>> edges;
    edges.reserve(M);

    for (int i = 0; i < M; ++i) {
        int u, v;
        cin >> u >> v;
        --u; --v;
        g[u].push_back(v);
        g[v].push_back(u);
        edges.push_back({u, v});
    }

    vector<int> comp(N, -1);
    int cid = 0;
    vector<bool> hasA, hasB, hasSame;

    for (int i = 0; i < N; ++i) {
        if (comp[i] != -1) continue;
        queue<int> q;
        q.push(i);
        comp[i] = cid;

        bool a = false, b = false;
        if (s[i] == 'A') a = true;
        else b = true;

        while (!q.empty()) {
            int u = q.front();
            q.pop();
            for (int v : g[u]) {
                if (comp[v] == -1) {
                    comp[v] = cid;
                    if (s[v] == 'A') a = true;
                    else b = true;
                    q.push(v);
                }
            }
        }

        hasA.push_back(a);
        hasB.push_back(b);
        hasSame.push_back(false);
        cid++;
    }

    for (auto [u, v] : edges) {
        if (comp[u] == comp[v] && s[u] == s[v]) {
            hasSame[comp[u]] = true;
        }
    }

    for (int c = 0; c < cid; ++c) {
        if (hasA[c] && hasB[c] && hasSame[c]) {
            cout << "Yes\n";
            return 0;
        }
    }

    cout << "No\n";
    return 0;
}

