import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            if (c == -1) return null;
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static int N, M;
    static char[] label;
    static ArrayList<Integer>[] g;

    static boolean[] vis;
    static boolean[] color;
    static boolean isBipartite;

    static void dfsBipartite(int start) {
        ArrayDeque<Integer> stack = new ArrayDeque<>();
        stack.push(start);
        vis[start] = true;
        color[start] = false;

        while (!stack.isEmpty()) {
            int u = stack.pop();
            for (int v : g[u]) {
                if (!vis[v]) {
                    vis[v] = true;
                    color[v] = !color[u];
                    stack.push(v);
                } else if (color[v] == color[u]) {
                    isBipartite = false;
                    return;
                }
            }
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        N = fs.nextInt();
        M = fs.nextInt();

        String s = fs.next();
        label = (" " + s).toCharArray();

        g = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) g[i] = new ArrayList<>();

        boolean hasAA = false, hasBB = false, hasAB = false;

        for (int i = 0; i < M; i++) {
            int u = fs.nextInt();
            int v = fs.nextInt();
            g[u].add(v);
            g[v].add(u);

            if (label[u] == 'A' && label[v] == 'A') hasAA = true;
            else if (label[u] == 'B' && label[v] == 'B') hasBB = true;
            else hasAB = true;
        }

        // To generate every binary string, it is sufficient and necessary that
        // every length-2 pattern (AA, AB, BA, BB) can appear as consecutive labels
        // on some walk. Since the graph is undirected, AB and BA are equivalent,
        // so we need edges of types AA, AB, and BB.
        //
        // If all three exist, then we can realize any desired next character:
        // - from A to A using an AA edge, from A to B using an AB edge
        // - from B to B using a BB edge, from B to A using an AB edge
        // hence any binary string can be traced as a walk.
        //
        // If one of AA / AB / BB is missing, the corresponding consecutive pair
        // can never appear, so not all strings are possible.

        System.out.println((hasAA && hasAB && hasBB) ? "Yes" : "No");
    }
}

import sys
input = sys.stdin.readline

def solve():
    n, m = map(int, input().split())
    labels = input().strip()

    edges = []
    for _ in range(m):
        u, v = map(int, input().split())
        edges.append((u-1, v-1))

    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Check we have both labels
    has_a = any(labels[i] == 'A' for i in range(n))
    has_b = any(labels[i] == 'B' for i in range(n))
    if not has_a or not has_b:
        print("NO")
        return

    # Check for A-A edge
    aa = False
    for u, v in edges:
        if labels[u] == 'A' and labels[v] == 'A':
            aa = True
            break
    # Check for B-B edge
    bb = False
    for u, v in edges:
        if labels[u] == 'B' and labels[v] == 'B':
            bb = True
            break
    # Check for A-B edge
    ab = False
    for u, v in edges:
        if labels[u] != labels[v]:
            ab = True
            break

    if aa and bb and ab:
        print("YES")
    else:
        print("NO")

if __name__ == "__main__":
    solve()
